import{_ as i,o as l,c as e,a2 as o}from"./chunks/framework.BauHmMU1.js";const _=JSON.parse('{"title":"第 10 章 生产环境最佳实践清单","description":"","frontmatter":{},"headers":[],"relativePath":"10-production-checklist.md","filePath":"10-production-checklist.md","lastUpdated":1792595797000}'),r={name:"10-production-checklist.md"};function a(c,t,n,s,d,u){return l(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="第-10-章-生产环境最佳实践清单" tabindex="-1">第 10 章 生产环境最佳实践清单 <a class="header-anchor" href="#第-10-章-生产环境最佳实践清单" aria-label="Permalink to &quot;第 10 章 生产环境最佳实践清单&quot;">​</a></h1><p><strong>连接可靠性</strong></p><ul><li>[ ] 实现指数退避 + full jitter 自动重连，重连成功后重置计数</li><li>[ ] 区分&quot;用户主动关闭&quot;与&quot;意外断开&quot;，前者不重连</li><li>[ ] 协议级心跳（服务端发起）+ 应用级看门狗（客户端发起）双保险</li><li>[ ] 每次重连前清理旧定时器，避免多定时器并存</li><li>[ ] 重连后自动恢复会话状态（重新 join 房间、拉取丢失期间的消息）</li></ul><p><strong>消息可靠性</strong></p><ul><li>[ ] 关键业务消息实现应用层 ACK + 幂等去重（clientId）</li><li>[ ] 消息体带时间戳/序号，客户端可对账检测丢消息</li><li>[ ] 发送前检查 <code>readyState === OPEN</code>，失败消息入队等重连后重发</li></ul><p><strong>安全</strong>（完整说明与实战见第 7 章）</p><ul><li>[ ] 生产环境只用 <code>wss://</code>（TLS 加密），HTTP 页面跳转 HTTPS</li><li>[ ] 握手阶段鉴权，失败返回 401 或建立后立即 close(1008)</li><li>[ ] 服务端校验 Origin 头，防跨站 WebSocket 劫持（CSWSH）</li><li>[ ] 限制单 IP 连接数、单连接消息频率与消息大小（防 DoS）</li><li>[ ] 每条敏感消息做业务级授权；不信任客户端发来的任何数据，JSON 解析必须 try-catch</li><li>[ ] 前端用 <code>textContent</code> 安全渲染用户内容，杜绝 XSS</li></ul><p><strong>性能</strong></p><ul><li>[ ] 广播时检查 readyState，异常发送用 try-catch/gather 隔离</li><li>[ ] 高频场景：ref 缓冲 + requestAnimationFrame 整批渲染，避免每条消息触发一次重绘</li><li>[ ] 消息列表窗口化（如存 1000 条渲染 60 条），防 DOM 膨胀</li><li>[ ] 大流量考虑二进制协议与消息合并</li></ul><hr>',10)])])}const S=i(r,[["render",a]]);export{_ as __pageData,S as default};
